import React, { useState } from 'react';
import api from '../services/api';
import { format, startOfWeek, addDays } from 'date-fns';

export function ExportPage() {
  const [weekDate, setWeekDate] = useState<Date>(startOfWeek(new Date(), { weekStartsOn: 1 }));
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleExport() {
    try {
      setError(null);
      setLoading(true);

      const weekStart = format(weekDate, 'yyyy-MM-dd');
      const blob = await api.exportToExcel(weekStart);

      // Create download link
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `timesheets-${weekStart}.xlsx`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to export');
    } finally {
      setLoading(false);
    }
  }

  const weekEnd = format(addDays(weekDate, 6), 'MMM dd, yyyy');
  const weekStart = format(weekDate, 'MMM dd, yyyy');

  return (
    <div>
      <div className="max-w-2xl mx-auto bg-white rounded-lg shadow p-8">
        <h2 className="text-2xl font-bold text-gray-900 mb-6">Export Timesheets</h2>

        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
            {error}
          </div>
        )}

        <div className="mb-8">
          <label className="block text-sm font-medium text-gray-700 mb-4">Select Week</label>
          <div className="flex items-center gap-4 mb-6">
            <button
              onClick={() => setWeekDate(addDays(weekDate, -7))}
              className="px-4 py-2 bg-gray-100 hover:bg-gray-200 rounded-lg font-medium"
            >
              Previous Week
            </button>

            <div className="flex-1 text-center">
              <p className="text-lg font-semibold text-gray-900">
                {weekStart} to {weekEnd}
              </p>
            </div>

            <button
              onClick={() => setWeekDate(addDays(weekDate, 7))}
              className="px-4 py-2 bg-gray-100 hover:bg-gray-200 rounded-lg font-medium"
            >
              Next Week
            </button>
          </div>

          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-6">
            <p className="text-sm text-blue-700">
              The export includes all approved timesheets for the selected week with:
            </p>
            <ul className="text-sm text-blue-700 mt-2 ml-4 list-disc">
              <li>Summary sheet with project totals</li>
              <li>Individual sheets for each project</li>
              <li>All-projects summary with financial metrics</li>
              <li>Professional formatting ready to share</li>
            </ul>
          </div>
        </div>

        <div className="flex gap-4">
          <button
            onClick={handleExport}
            disabled={loading}
            className="flex-1 px-6 py-3 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white font-bold rounded-lg transition-colors"
          >
            {loading ? 'Exporting...' : 'Export to Excel'}
          </button>

          <div className="flex-1 bg-gray-50 p-4 rounded-lg">
            <p className="text-sm text-gray-600">Format</p>
            <p className="font-semibold text-gray-900">Excel (.xlsx)</p>
          </div>
        </div>

        <div className="mt-8 pt-8 border-t">
          <h3 className="text-lg font-bold text-gray-900 mb-4">Export Format Details</h3>
          <div className="space-y-4">
            <div>
              <h4 className="font-semibold text-gray-900">Summary Sheet</h4>
              <p className="text-sm text-gray-600">
                Overview of all projects with total hours, OT, and amounts
              </p>
            </div>
            <div>
              <h4 className="font-semibold text-gray-900">Project Sheets</h4>
              <p className="text-sm text-gray-600">
                Detailed timesheet for each project showing employee hours by day
              </p>
            </div>
            <div>
              <h4 className="font-semibold text-gray-900">All Projects</h4>
              <p className="text-sm text-gray-600">
                Consolidated view with supervisor information and financial summary
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
